#define CONST_FT_RFORK_RULE_ARRAY_BEGIN( name, type )  \
		  static const type name[] = {
#define CONST_FT_RFORK_RULE_ARRAY_ENTRY( func_suffix, type_suffix )  \
		  { raccess_guess_ ## func_suffix,                           \
