  FT_LOCAL_DEF( void )
  af_sort_pos( FT_UInt  count,
			   FT_Pos*  table )
  {
	FT_UInt  i, j;
	FT_Pos   swap;

	for ( i = 1; i < count; i++ )
	{
	  for ( j = i; j > 0; j-- )
	  {
		if ( table[j] >= table[j - 1] )
		  break;

		swap         = table[j];
		table[j]     = table[j - 1];
		table[j - 1] = swap;
	  }
	}
  }

  FT_LOCAL_DEF( void )
  af_sort_and_quantize_widths( FT_UInt*  count,
							   AF_Width  table,
							   FT_Pos    threshold )
  {
	FT_UInt      i, j;
	FT_UInt      cur_idx;
	FT_Pos       cur_val;
	FT_Pos       sum;
	AF_WidthRec  swap;

	if ( *count == 1 )
	  return;

	/* sort */
	for ( i = 1; i < *count; i++ )
	{
	  for ( j = i; j > 0; j-- )
	  {
		if ( table[j].org >= table[j - 1].org )
		  break;

		swap         = table[j];
		table[j]     = table[j - 1];
		table[j - 1] = swap;
	  }
	}

	cur_idx = 0;
	cur_val = table[cur_idx].org;

	/* compute and use mean values for clusters not larger than  */
	/* `threshold'; this is very primitive and might not yield   */
	/* the best result, but normally, using reference character  */
	/* `o', `*count' is 2, so the code below is fully sufficient */
	for ( i = 1; i < *count; i++ )
	{
	  if ( table[i].org - cur_val > threshold ||
		   i == *count - 1                    )
	  {
		sum = 0;

		/* fix loop for end of array */
		if ( table[i].org - cur_val <= threshold &&
			 i == *count - 1                     )
		  i++;

		for ( j = cur_idx; j < i; j++ )
		{
		  sum         += table[j].org;
		  table[j].org = 0;
		}
		table[cur_idx].org = sum / (FT_Pos)j;

		if ( i < *count - 1 )
		{
		  cur_idx = i + 1;
		  cur_val = table[cur_idx].org;
		}
	  }
	}

	cur_idx = 1;

	/* compress array to remove zero values */
	for ( i = 1; i < *count; i++ )
	{
	  if ( table[i].org )
		table[cur_idx++] = table[i];
	}

	*count = cur_idx;
  }

  /* Get new segment for given axis. */

  FT_LOCAL_DEF( FT_Error )
  af_axis_hints_new_segment( AF_AxisHints  axis,
							 FT_Memory     memory,
							 AF_Segment   *asegment )
  {
	FT_Error    error   = FT_Err_Ok;
	AF_Segment  segment = NULL;

	if ( axis->num_segments < AF_SEGMENTS_EMBEDDED )
	{
	  if ( !axis->segments )
	  {
		axis->segments     = axis->embedded.segments;
		axis->max_segments = AF_SEGMENTS_EMBEDDED;
	  }
	}
	else if ( axis->num_segments >= axis->max_segments )
	{
	  FT_UInt  old_max = axis->max_segments;
	  FT_UInt  new_max = old_max;
	  FT_UInt  big_max = FT_INT_MAX / sizeof ( *segment );

	  if ( old_max >= big_max )
	  {
		error = FT_THROW( Out_Of_Memory );
		goto Exit;
	  }

	  new_max += ( new_max >> 2 ) + 4;
	  if ( new_max < old_max || new_max > big_max )
		new_max = big_max;

	  if ( axis->segments == axis->embedded.segments )
	  {
		if ( FT_NEW_ARRAY( axis->segments, new_max ) )
		  goto Exit;
		ft_memcpy( axis->segments, axis->embedded.segments,
				   sizeof ( axis->embedded.segments ) );
	  }
	  else
	  {
		if ( FT_RENEW_ARRAY( axis->segments, old_max, new_max ) )
		  goto Exit;
	  }

	  axis->max_segments = new_max;
	}

	segment = axis->segments + axis->num_segments++;

  Exit:
	*asegment = segment;
	return error;
  }

  /* Get new edge for given axis, direction, and position, */
  /* without initializing the edge itself.                 */

  FT_LOCAL_DEF( FT_Error )
  af_axis_hints_new_edge( AF_AxisHints  axis,
						  FT_Int        fpos,
						  AF_Direction  dir,
						  FT_Bool       top_to_bottom_hinting,
						  FT_Memory     memory,
						  AF_Edge      *anedge )
  {
	FT_Error  error = FT_Err_Ok;
	AF_Edge   edge  = NULL;
	AF_Edge   edges;

	if ( axis->num_edges < AF_EDGES_EMBEDDED )
	{
	  if ( !axis->edges )
	  {
		axis->edges     = axis->embedded.edges;
		axis->max_edges = AF_EDGES_EMBEDDED;
	  }
	}
	else if ( axis->num_edges >= axis->max_edges )
	{
	  FT_UInt  old_max = axis->max_edges;
	  FT_UInt  new_max = old_max;
	  FT_UInt  big_max = FT_INT_MAX / sizeof ( *edge );

	  if ( old_max >= big_max )
	  {
		error = FT_THROW( Out_Of_Memory );
		goto Exit;
	  }

	  new_max += ( new_max >> 2 ) + 4;
	  if ( new_max < old_max || new_max > big_max )
		new_max = big_max;

	  if ( axis->edges == axis->embedded.edges )
	  {
		if ( FT_NEW_ARRAY( axis->edges, new_max ) )
		  goto Exit;
		ft_memcpy( axis->edges, axis->embedded.edges,
				   sizeof ( axis->embedded.edges ) );
	  }
	  else
	  {
		if ( FT_RENEW_ARRAY( axis->edges, old_max, new_max ) )
		  goto Exit;
	  }

	  axis->max_edges = new_max;
	}

	edges = axis->edges;
	edge  = edges + axis->num_edges;

	while ( edge > edges )
	{
	  if ( top_to_bottom_hinting ? ( edge[-1].fpos > fpos )
								 : ( edge[-1].fpos < fpos ) )
		break;

	  /* we want the edge with same position and minor direction */
	  /* to appear before those in the major one in the list     */
	  if ( edge[-1].fpos == fpos && dir == axis->major_dir )
		break;

	  edge[0] = edge[-1];
	  edge--;
	}

	axis->num_edges++;

  Exit:
	*anedge = edge;
	return error;
  }

