  const char*
  af_shaper_get_cluster( const char*      p,
						 AF_StyleMetrics  metrics,
						 void*            buf_,
						 unsigned int*    count )
  {
	FT_Face    face      = metrics->globals->face;
	FT_ULong   ch, dummy = 0;
	FT_ULong*  buf       = (FT_ULong*)buf_;

	while ( *p == ' ' )
	  p++;

	GET_UTF8_CHAR( ch, p );

	/* since we don't have an engine to handle clusters, */
	/* we scan the characters but return zero            */
	while ( !( *p == ' ' || *p == '\0' ) )
	  GET_UTF8_CHAR( dummy, p );

	if ( dummy )
	{
	  *buf   = 0;
	  *count = 0;
	}
	else
	{
	  *buf   = FT_Get_Char_Index( face, ch );
	  *count = 1;
	}

	return p;
  }

  FT_ULong
  af_shaper_get_elem( AF_StyleMetrics  metrics,
					  void*            buf_,
					  unsigned int     idx,
					  FT_Long*         advance,
					  FT_Long*         y_offset )
  {
	FT_Face   face        = metrics->globals->face;
	FT_ULong  glyph_index = *(FT_ULong*)buf_;

	FT_UNUSED( idx );

	if ( advance )
	  FT_Get_Advance( face,
					  glyph_index,
					  FT_LOAD_NO_SCALE         |
					  FT_LOAD_NO_HINTING       |
					  FT_LOAD_IGNORE_TRANSFORM,
					  advance );

	if ( y_offset )
	  *y_offset = 0;

	return glyph_index;
  }

#endif /* !FT_CONFIG_OPTION_USE_HARFBUZZ */

