#define PS_MAX_OPERANDS        48
#define PS_MAX_SUBRS_CALLS     16   /* maximum subroutine nesting;         */
									/* only 10 are allowed but there exist */
									/* fonts like `HiraKakuProN-W3.ttf'    */
									/* (Hiragino Kaku Gothic ProN W3;      */
									/* 8.2d6e1; 2014-12-19) that exceed    */
									/* this limit                          */

  /* execution context charstring zone */

  typedef struct  PS_Decoder_Zone_
  {
	FT_Byte*  base;
	FT_Byte*  limit;
	FT_Byte*  cursor;

  } PS_Decoder_Zone;

  typedef FT_Error
  (*CFF_Decoder_Get_Glyph_Callback)( TT_Face    face,
									 FT_UInt    glyph_index,
									 FT_Byte**  pointer,
									 FT_ULong*  length );

  typedef void
  (*CFF_Decoder_Free_Glyph_Callback)( TT_Face    face,
									  FT_Byte**  pointer,
									  FT_ULong   length );

  typedef struct  PS_Decoder_
  {
	PS_Builder  builder;

	FT_Fixed   stack[PS_MAX_OPERANDS + 1];
	FT_Fixed*  top;

	PS_Decoder_Zone   zones[PS_MAX_SUBRS_CALLS + 1];
	PS_Decoder_Zone*  zone;

	FT_Int     flex_state;
	FT_Int     num_flex_vectors;
	FT_Vector  flex_vectors[7];

	CFF_Font     cff;
	CFF_SubFont  current_subfont; /* for current glyph_index */
	FT_Generic*  cf2_instance;

	FT_Pos*  glyph_width;
	FT_Bool  width_only;
	FT_Int   num_hints;

	FT_UInt  num_locals;
	FT_UInt  num_globals;

	FT_Int  locals_bias;
	FT_Int  globals_bias;

	FT_Byte**  locals;
	FT_Byte**  globals;

	FT_Byte**  glyph_names;   /* for pure CFF fonts only  */
	FT_UInt    num_glyphs;    /* number of glyphs in font */

	FT_Render_Mode  hint_mode;

	FT_Bool  seac;

	CFF_Decoder_Get_Glyph_Callback   get_glyph_callback;
	CFF_Decoder_Free_Glyph_Callback  free_glyph_callback;

	/* Type 1 stuff */
	FT_Service_PsCMaps  psnames;      /* for seac */

	FT_Int    lenIV;         /* internal for sub routine calls   */
	FT_UInt*  locals_len;    /* array of subrs length (optional) */
	FT_Hash   locals_hash;   /* used if `num_subrs' was massaged */

	FT_Matrix  font_matrix;
	FT_Vector  font_offset;

	PS_Blend  blend;         /* for multiple master support */

	FT_Long*  buildchar;
	FT_UInt   len_buildchar;

  } PS_Decoder;

