  static FT_Error
  raccess_guess_apple_generic( FT_Library  library,
							   FT_Stream   stream,
							   char       *base_file_name,
							   FT_Int32    magic,
							   FT_Long    *result_offset );

  static FT_Error
  raccess_guess_linux_double_from_file_name( FT_Library  library,
											 char*       file_name,
											 FT_Long    *result_offset );

  static char *
  raccess_make_file_name( FT_Memory    memory,
						  const char  *original_name,
						  const char  *insertion );

  FT_BASE_DEF( void )
  FT_Raccess_Guess( FT_Library  library,
					FT_Stream   stream,
					char*       base_name,
					char      **new_names,
					FT_Long    *offsets,
					FT_Error   *errors )
  {
	FT_Int  i;

	for ( i = 0; i < FT_RACCESS_N_RULES; i++ )
	{
	  new_names[i] = NULL;
	  if ( NULL != stream )
		errors[i] = FT_Stream_Seek( stream, 0 );
	  else
		errors[i] = FT_Err_Ok;

	  if ( errors[i] )
		continue;

	  errors[i] = ft_raccess_guess_table[i].func( library,
												  stream, base_name,
												  &(new_names[i]),
												  &(offsets[i]) );
	}

	return;
  }

#if defined( FT_CONFIG_OPTION_MAC_FONTS ) && !defined( FT_MACINTOSH )
  static FT_RFork_Rule
  raccess_get_rule_type_from_rule_index( FT_Library  library,
										 FT_UInt     rule_index )
  {
	FT_UNUSED( library );

	if ( rule_index >= FT_RACCESS_N_RULES )
	  return FT_RFork_Rule_invalid;

	return ft_raccess_guess_table[rule_index].type;
  }

  /*
   * For this function, refer ftbase.h.
   */
  FT_LOCAL_DEF( FT_Bool )
  ft_raccess_rule_by_darwin_vfs( FT_Library  library,
								 FT_UInt     rule_index )
  {
	switch( raccess_get_rule_type_from_rule_index( library, rule_index ) )
	{
	  case FT_RFork_Rule_darwin_newvfs:
	  case FT_RFork_Rule_darwin_hfsplus:
		return TRUE;

	  default:
		return FALSE;
	}
  }
#endif

  static FT_Error
  raccess_guess_apple_double( FT_Library  library,
							  FT_Stream   stream,
							  char       *base_file_name,
							  char      **result_file_name,
							  FT_Long    *result_offset )
  {
	FT_Int32  magic = ( 0x00 << 24 ) |
					  ( 0x05 << 16 ) |
					  ( 0x16 <<  8 ) |
						0x07;

	*result_file_name = NULL;
	if ( NULL == stream )
	  return FT_THROW( Cannot_Open_Stream );

	return raccess_guess_apple_generic( library, stream, base_file_name,
										magic, result_offset );
  }

  static FT_Error
  raccess_guess_apple_single( FT_Library  library,
							  FT_Stream   stream,
							  char       *base_file_name,
							  char      **result_file_name,
							  FT_Long    *result_offset )
  {
	FT_Int32  magic = ( 0x00 << 24 ) |
					  ( 0x05 << 16 ) |
					  ( 0x16 <<  8 ) |
						0x00;

	*result_file_name = NULL;
	if ( NULL == stream )
	  return FT_THROW( Cannot_Open_Stream );

	return raccess_guess_apple_generic( library, stream, base_file_name,
										magic, result_offset );
  }

  static FT_Error
  raccess_guess_darwin_ufs_export( FT_Library  library,
								   FT_Stream   stream,
								   char       *base_file_name,
								   char      **result_file_name,
								   FT_Long    *result_offset )
  {
	char*      newpath;
	FT_Error   error;
	FT_Memory  memory;

	FT_UNUSED( stream );

	memory  = library->memory;
	newpath = raccess_make_file_name( memory, base_file_name, "._" );
	if ( !newpath )
	  return FT_THROW( Out_Of_Memory );

	error = raccess_guess_linux_double_from_file_name( library, newpath,
													   result_offset );
	if ( !error )
	  *result_file_name = newpath;
	else
	  FT_FREE( newpath );

	return error;
  }

  static FT_Error
  raccess_guess_darwin_hfsplus( FT_Library  library,
								FT_Stream   stream,
								char       *base_file_name,
								char      **result_file_name,
								FT_Long    *result_offset )
  {
	/*
	  Only meaningful on systems with hfs+ drivers (or Macs).
	 */
	FT_Error   error;
	char*      newpath = NULL;
	FT_Memory  memory;
	FT_Long    base_file_len = (FT_Long)ft_strlen( base_file_name );

	FT_UNUSED( stream );

	memory = library->memory;

	if ( base_file_len + 6 > FT_INT_MAX )
	  return FT_THROW( Array_Too_Large );

	if ( FT_QALLOC( newpath, base_file_len + 6 ) )
	  return error;

	FT_MEM_COPY( newpath, base_file_name, base_file_len );
	FT_MEM_COPY( newpath + base_file_len, "/rsrc", 6 );

	*result_file_name = newpath;
	*result_offset    = 0;

	return FT_Err_Ok;
  }

  static FT_Error
  raccess_guess_darwin_newvfs( FT_Library  library,
							   FT_Stream   stream,
							   char       *base_file_name,
							   char      **result_file_name,
							   FT_Long    *result_offset )
  {
	/*
	  Only meaningful on systems with Mac OS X (> 10.1).
	 */
	FT_Error   error;
	char*      newpath = NULL;
	FT_Memory  memory;
	FT_Long    base_file_len = (FT_Long)ft_strlen( base_file_name );

	FT_UNUSED( stream );

	memory = library->memory;

	if ( base_file_len + 18 > FT_INT_MAX )
	  return FT_THROW( Array_Too_Large );

	if ( FT_QALLOC( newpath, base_file_len + 18 ) )
	  return error;

	FT_MEM_COPY( newpath, base_file_name, base_file_len );
	FT_MEM_COPY( newpath + base_file_len, "/..namedfork/rsrc", 18 );

	*result_file_name = newpath;
	*result_offset    = 0;

	return FT_Err_Ok;
  }

