  {
	FT_UNUSED( face );
	FT_UNUSED( langID );
	FT_UNUSED( alangTag );

	return FT_THROW( Unimplemented_Feature );
  }

#endif /* !TT_CONFIG_OPTION_SFNT_NAMES */

