#undef  FT_COMPONENT
#define FT_COMPONENT  list

  /* documentation is in ftlist.h */

  FT_EXPORT_DEF( FT_ListNode )
  FT_List_Find( FT_List  list,
				void*    data )
  {
	FT_ListNode  cur;

	if ( !list )
	  return NULL;

	cur = list->head;
	while ( cur )
	{
	  if ( cur->data == data )
		return cur;

	  cur = cur->next;
	}

	return NULL;
  }

  /* documentation is in ftlist.h */

  FT_EXPORT_DEF( void )
  FT_List_Add( FT_List      list,
			   FT_ListNode  node )
  {
	FT_ListNode  before;

	if ( !list || !node )
	  return;

	before = list->tail;

	node->next = NULL;
	node->prev = before;

	if ( before )
	  before->next = node;
	else
	  list->head = node;

	list->tail = node;
  }

  /* documentation is in ftlist.h */

  FT_EXPORT_DEF( void )
  FT_List_Insert( FT_List      list,
				  FT_ListNode  node )
  {
	FT_ListNode  after;

	if ( !list || !node )
	  return;

	after = list->head;

	node->next = after;
	node->prev = NULL;

	if ( !after )
	  list->tail = node;
	else
	  after->prev = node;

	list->head = node;
  }

  /* documentation is in ftlist.h */

  FT_EXPORT_DEF( void )
  FT_List_Remove( FT_List      list,
				  FT_ListNode  node )
  {
	FT_ListNode  before, after;

	if ( !list || !node )
	  return;

	before = node->prev;
	after  = node->next;

	if ( before )
	  before->next = after;
	else
	  list->head = after;

	if ( after )
	  after->prev = before;
	else
	  list->tail = before;
  }

  /* documentation is in ftlist.h */

  FT_EXPORT_DEF( void )
  FT_List_Up( FT_List      list,
			  FT_ListNode  node )
  {
	FT_ListNode  before, after;

	if ( !list || !node )
	  return;

	before = node->prev;
	after  = node->next;

	/* check whether we are already on top of the list */
	if ( !before )
	  return;

	before->next = after;

	if ( after )
	  after->prev = before;
	else
	  list->tail = before;

	node->prev       = NULL;
	node->next       = list->head;
	list->head->prev = node;
	list->head       = node;
  }

  /* documentation is in ftlist.h */

  FT_EXPORT_DEF( FT_Error )
  FT_List_Iterate( FT_List           list,
				   FT_List_Iterator  iterator,
				   void*             user )
  {
	FT_ListNode  cur;
	FT_Error     error = FT_Err_Ok;

	if ( !list || !iterator )
	  return FT_THROW( Invalid_Argument );

	cur = list->head;

	while ( cur )
	{
	  FT_ListNode  next = cur->next;

	  error = iterator( cur, user );
	  if ( error )
		break;

	  cur = next;
	}

	return error;
  }

  /* documentation is in ftlist.h */

  FT_EXPORT_DEF( void )
  FT_List_Finalize( FT_List             list,
					FT_List_Destructor  destroy,
					FT_Memory           memory,
					void*               user )
  {
	FT_ListNode  cur;

	if ( !list || !memory )
	  return;

	cur = list->head;
	while ( cur )
	{
	  FT_ListNode  next = cur->next;
	  void*        data = cur->data;

	  if ( destroy )
		destroy( memory, data, user );

	  FT_FREE( cur );
	  cur = next;
	}

	list->head = NULL;
	list->tail = NULL;
  }

