  /*
   * Basic Families
   *
   */
  typedef struct  FTC_BasicAttrRec_
  {
	FTC_ScalerRec  scaler;
	FT_UInt        load_flags;

  } FTC_BasicAttrRec, *FTC_BasicAttrs;

#define FTC_BASIC_ATTR_COMPARE( a, b )                                 \
		  FT_BOOL( FTC_SCALER_COMPARE( &(a)->scaler, &(b)->scaler ) && \
				   (a)->load_flags == (b)->load_flags               )

#define FTC_BASIC_ATTR_HASH( a )                                     \
		  ( FTC_SCALER_HASH( &(a)->scaler ) + 31 * (a)->load_flags )

  typedef struct  FTC_BasicQueryRec_
  {
	FTC_GQueryRec     gquery;
	FTC_BasicAttrRec  attrs;

  } FTC_BasicQueryRec, *FTC_BasicQuery;

  typedef struct  FTC_BasicFamilyRec_
  {
	FTC_FamilyRec     family;
	FTC_BasicAttrRec  attrs;

  } FTC_BasicFamilyRec, *FTC_BasicFamily;

  FT_CALLBACK_DEF( FT_Bool )
  ftc_basic_family_compare( FTC_MruNode  ftcfamily,
							FT_Pointer   ftcquery )
  {
	FTC_BasicFamily  family = (FTC_BasicFamily)ftcfamily;
	FTC_BasicQuery   query  = (FTC_BasicQuery)ftcquery;

	return FTC_BASIC_ATTR_COMPARE( &family->attrs, &query->attrs );
  }

  FT_CALLBACK_DEF( FT_Error )
  ftc_basic_family_init( FTC_MruNode  ftcfamily,
						 FT_Pointer   ftcquery,
						 FT_Pointer   ftccache )
  {
	FTC_BasicFamily  family = (FTC_BasicFamily)ftcfamily;
	FTC_BasicQuery   query  = (FTC_BasicQuery)ftcquery;
	FTC_Cache        cache  = (FTC_Cache)ftccache;

	FTC_Family_Init( FTC_FAMILY( family ), cache );
	family->attrs = query->attrs;
	return 0;
  }

  FT_CALLBACK_DEF( FT_UInt )
  ftc_basic_family_get_count( FTC_Family   ftcfamily,
							  FTC_Manager  manager )
  {
	FTC_BasicFamily  family = (FTC_BasicFamily)ftcfamily;
	FT_Error         error;
	FT_Face          face;
	FT_UInt          result = 0;

	error = FTC_Manager_LookupFace( manager, family->attrs.scaler.face_id,
									&face );

	if ( error || !face )
	  return result;

#ifdef FT_DEBUG_LEVEL_TRACE
	if ( (FT_ULong)face->num_glyphs > FT_UINT_MAX || 0 > face->num_glyphs )
	{
	  FT_TRACE1(( "ftc_basic_family_get_count:"
				  " the number of glyphs in this face is %ld,\n",
				  face->num_glyphs ));
	  FT_TRACE1(( "                           "
				  " which is too much and thus truncated\n" ));
	}
#endif

	result = (FT_UInt)face->num_glyphs;

	return result;
  }

  FT_CALLBACK_DEF( FT_Error )
  ftc_basic_family_load_bitmap( FTC_Family   ftcfamily,
								FT_UInt      gindex,
								FTC_Manager  manager,
								FT_Face     *aface )
  {
	FTC_BasicFamily  family = (FTC_BasicFamily)ftcfamily;
	FT_Error         error;
	FT_Size          size;

	error = FTC_Manager_LookupSize( manager, &family->attrs.scaler, &size );
	if ( !error )
	{
	  FT_Face  face = size->face;

	  error = FT_Load_Glyph(
				face,
				gindex,
				(FT_Int)family->attrs.load_flags | FT_LOAD_RENDER );
	  if ( !error )
		*aface = face;
	}

	return error;
  }

  FT_CALLBACK_DEF( FT_Error )
  ftc_basic_family_load_glyph( FTC_Family  ftcfamily,
							   FT_UInt     gindex,
							   FTC_Cache   cache,
							   FT_Glyph   *aglyph )
  {
	FTC_BasicFamily  family = (FTC_BasicFamily)ftcfamily;
	FT_Error         error;
	FTC_Scaler       scaler = &family->attrs.scaler;
	FT_Face          face;
	FT_Size          size;

	/* we will now load the glyph image */
	error = FTC_Manager_LookupSize( cache->manager,
									scaler,
									&size );
	if ( !error )
	{
	  face = size->face;

	  error = FT_Load_Glyph( face,
							 gindex,
							 (FT_Int)family->attrs.load_flags );
	  if ( !error )
	  {
		if ( face->glyph->format == FT_GLYPH_FORMAT_BITMAP  ||
			 face->glyph->format == FT_GLYPH_FORMAT_OUTLINE ||
			 face->glyph->format == FT_GLYPH_FORMAT_SVG     )
		{
		  /* ok, copy it */
		  FT_Glyph  glyph;

		  error = FT_Get_Glyph( face->glyph, &glyph );
		  if ( !error )
		  {
			*aglyph = glyph;
			goto Exit;
		  }
		}
		else
		  error = FT_THROW( Invalid_Argument );
	  }
	}

  Exit:
	return error;
  }

  FT_CALLBACK_DEF( FT_Bool )
  ftc_basic_gnode_compare_faceid( FTC_Node    ftcgnode,
								  FT_Pointer  ftcface_id,
								  FTC_Cache   cache,
								  FT_Bool*    list_changed )
  {
	FTC_GNode        gnode   = (FTC_GNode)ftcgnode;
	FTC_FaceID       face_id = (FTC_FaceID)ftcface_id;
	FTC_BasicFamily  family  = (FTC_BasicFamily)gnode->family;
	FT_Bool          result;

	if ( list_changed )
	  *list_changed = FALSE;
	result = FT_BOOL( family->attrs.scaler.face_id == face_id );
	if ( result )
	{
	  /* we must call this function to avoid this node from appearing
	   * in later lookups with the same face_id!
	   */
	  FTC_GNode_UnselectFamily( gnode, cache );
	}
	return result;
  }

