  /* documentation is in ftcache.h */

  FT_EXPORT_DEF( FT_Error )
  FTC_ImageCache_Lookup( FTC_ImageCache  cache,
						 FTC_ImageType   type,
						 FT_UInt         gindex,
						 FT_Glyph       *aglyph,
						 FTC_Node       *anode )
  {
	FTC_BasicQueryRec  query;
	FTC_Node           node = 0; /* make compiler happy */
	FT_Error           error;
	FT_Offset          hash;

	/* some argument checks are delayed to `FTC_Cache_Lookup' */
	if ( !aglyph )
	{
	  error = FT_THROW( Invalid_Argument );
	  goto Exit;
	}

	*aglyph = NULL;
	if ( anode )
	  *anode  = NULL;

	/*
	 * Internal `FTC_BasicAttr->load_flags' is of type `FT_UInt',
	 * but public `FT_ImageType->flags' is of type `FT_Int32'.
	 *
	 * On 16bit systems, higher bits of type->flags cannot be handled.
	 */
#if 0xFFFFFFFFUL > FT_UINT_MAX
	if ( (type->flags & (FT_ULong)FT_UINT_MAX) )
	  FT_TRACE1(( "FTC_ImageCache_Lookup:"
				  " higher bits in load_flags 0x%lx are dropped\n",
				  (FT_ULong)type->flags & ~((FT_ULong)FT_UINT_MAX) ));
#endif

	query.attrs.scaler.face_id = type->face_id;
	query.attrs.scaler.width   = type->width;
	query.attrs.scaler.height  = type->height;
	query.attrs.load_flags     = (FT_UInt)type->flags;

	query.attrs.scaler.pixel = 1;
	query.attrs.scaler.x_res = 0;  /* make compilers happy */
	query.attrs.scaler.y_res = 0;

	hash = FTC_BASIC_ATTR_HASH( &query.attrs ) + gindex;

#if 1  /* inlining is about 50% faster! */
	FTC_GCACHE_LOOKUP_CMP( cache,
						   ftc_basic_family_compare,
						   ftc_gnode_compare,
						   hash, gindex,
						   &query,
						   node,
						   error );
#else
	error = FTC_GCache_Lookup( FTC_GCACHE( cache ),
							   hash, gindex,
							   FTC_GQUERY( &query ),
							   &node );
#endif
	if ( !error )
	{
	  *aglyph = FTC_INODE( node )->glyph;

	  if ( anode )
	  {
		*anode = node;
		node->ref_count++;
	  }
	}

  Exit:
	return error;
  }

  /* documentation is in ftcache.h */

  FT_EXPORT_DEF( FT_Error )
  FTC_ImageCache_LookupScaler( FTC_ImageCache  cache,
							   FTC_Scaler      scaler,
							   FT_ULong        load_flags,
							   FT_UInt         gindex,
							   FT_Glyph       *aglyph,
							   FTC_Node       *anode )
  {
	FTC_BasicQueryRec  query;
	FTC_Node           node = 0; /* make compiler happy */
	FT_Error           error;
	FT_Offset          hash;

	/* some argument checks are delayed to `FTC_Cache_Lookup' */
	if ( !aglyph || !scaler )
	{
	  error = FT_THROW( Invalid_Argument );
	  goto Exit;
	}

	*aglyph = NULL;
	if ( anode )
	  *anode  = NULL;

	/*
	 * Internal `FTC_BasicAttr->load_flags' is of type `FT_UInt',
	 * but public `FT_Face->face_flags' is of type `FT_Long'.
	 *
	 * On long > int systems, higher bits of load_flags cannot be handled.
	 */
#if FT_ULONG_MAX > FT_UINT_MAX
	if ( load_flags > FT_UINT_MAX )
	  FT_TRACE1(( "FTC_ImageCache_LookupScaler:"
				  " higher bits in load_flags 0x%lx are dropped\n",
				  load_flags & ~((FT_ULong)FT_UINT_MAX) ));
#endif

	query.attrs.scaler     = scaler[0];
	query.attrs.load_flags = (FT_UInt)load_flags;

	hash = FTC_BASIC_ATTR_HASH( &query.attrs ) + gindex;

	FTC_GCACHE_LOOKUP_CMP( cache,
						   ftc_basic_family_compare,
						   ftc_gnode_compare,
						   hash, gindex,
						   &query,
						   node,
						   error );
	if ( !error )
	{
	  *aglyph = FTC_INODE( node )->glyph;

	  if ( anode )
	  {
		*anode = node;
		node->ref_count++;
	  }
	}

  Exit:
	return error;
  }

