  FT_EXPORT_DEF( FT_Error )
  FTC_Manager_New( FT_Library          library,
				   FT_UInt             max_faces,
				   FT_UInt             max_sizes,
				   FT_ULong            max_bytes,
				   FTC_Face_Requester  requester,
				   FT_Pointer          req_data,
				   FTC_Manager        *amanager )
  {
	FT_Error     error;
	FT_Memory    memory;
	FTC_Manager  manager = NULL;

	if ( !library )
	  return FT_THROW( Invalid_Library_Handle );

	if ( !amanager || !requester )
	  return FT_THROW( Invalid_Argument );

	memory = library->memory;

	if ( FT_QNEW( manager ) )
	  goto Exit;

	if ( max_faces == 0 )
	  max_faces = FTC_MAX_FACES_DEFAULT;

	if ( max_sizes == 0 )
	  max_sizes = FTC_MAX_SIZES_DEFAULT;

	if ( max_bytes == 0 )
	  max_bytes = FTC_MAX_BYTES_DEFAULT;

	manager->library      = library;
	manager->memory       = memory;
	manager->max_weight   = max_bytes;
	manager->cur_weight   = 0;

	manager->request_face = requester;
	manager->request_data = req_data;

	FTC_MruList_Init( &manager->faces,
					  &ftc_face_list_class,
					  max_faces,
					  manager,
					  memory );

	FTC_MruList_Init( &manager->sizes,
					  &ftc_size_list_class,
					  max_sizes,
					  manager,
					  memory );

	manager->nodes_list = NULL;
	manager->num_nodes  = 0;
	manager->num_caches = 0;

	*amanager = manager;

  Exit:
	return error;
  }

  /* documentation is in ftcache.h */

  FT_EXPORT_DEF( void )
  FTC_Manager_Done( FTC_Manager  manager )
  {
	FT_Memory  memory;
	FT_UInt    idx;

	if ( !manager || !manager->library )
	  return;

	memory = manager->memory;

	/* now discard all caches */
	for ( idx = manager->num_caches; idx-- > 0; )
	{
	  FTC_Cache  cache = manager->caches[idx];

	  if ( cache )
	  {
		cache->clazz.cache_done( cache );
		FT_FREE( cache );
		manager->caches[idx] = NULL;
	  }
	}
	manager->num_caches = 0;

	/* discard faces and sizes */
	FTC_MruList_Done( &manager->sizes );
	FTC_MruList_Done( &manager->faces );

	manager->library = NULL;
	manager->memory  = NULL;

	FT_FREE( manager );
  }

  /* documentation is in ftcache.h */

  FT_EXPORT_DEF( void )
  FTC_Manager_Reset( FTC_Manager  manager )
  {
	if ( !manager )
	  return;

	FTC_MruList_Reset( &manager->sizes );
	FTC_MruList_Reset( &manager->faces );

	FTC_Manager_FlushN( manager, manager->num_nodes );
  }

#ifdef FT_DEBUG_ERROR

  static void
  FTC_Manager_Check( FTC_Manager  manager )
  {
	FTC_Node  node, first;

	first = manager->nodes_list;

	/* check node weights */
	if ( first )
	{
	  FT_Offset  weight = 0;

	  node = first;

	  do
	  {
		FTC_Cache  cache = manager->caches[node->cache_index];

		if ( node->cache_index >= manager->num_caches )
		  FT_TRACE0(( "FTC_Manager_Check: invalid node (cache index = %hu\n",
					  node->cache_index ));
		else
		  weight += cache->clazz.node_weight( node, cache );

		node = FTC_NODE_NEXT( node );

	  } while ( node != first );

	  if ( weight != manager->cur_weight )
		FT_TRACE0(( "FTC_Manager_Check: invalid weight %ld instead of %ld\n",
					manager->cur_weight, weight ));
	}

	/* check circular list */
	if ( first )
	{
	  FT_UFast  count = 0;

	  node = first;
	  do
	  {
		count++;
		node = FTC_NODE_NEXT( node );

	  } while ( node != first );

	  if ( count != manager->num_nodes )
		FT_TRACE0(( "FTC_Manager_Check:"
					" invalid cache node count %u instead of %u\n",
					manager->num_nodes, count ));
	}
  }

#endif /* FT_DEBUG_ERROR */

  /* `Compress' the manager's data, i.e., get rid of old cache nodes */
  /* that are not referenced anymore in order to limit the total     */
  /* memory used by the cache.                                       */

  /* documentation is in ftcmanag.h */

  FT_LOCAL_DEF( void )
  FTC_Manager_Compress( FTC_Manager  manager )
  {
	FTC_Node   node, prev, first;

	if ( !manager )
	  return;

	first = manager->nodes_list;

#ifdef FT_DEBUG_ERROR
	FTC_Manager_Check( manager );

	FT_TRACE0(( "compressing, weight = %ld, max = %ld, nodes = %u\n",
				manager->cur_weight, manager->max_weight,
				manager->num_nodes ));
#endif

	if ( manager->cur_weight < manager->max_weight || !first )
	  return;

	/* go to last node -- it's a circular list */
	prev = FTC_NODE_PREV( first );
	do
	{
	  node = prev;
	  prev = FTC_NODE_PREV( node );

	  if ( node->ref_count <= 0 )
		ftc_node_destroy( node, manager );

	} while ( node != first && manager->cur_weight > manager->max_weight );
  }

  /* documentation is in ftcmanag.h */

  FT_LOCAL_DEF( FT_Error )
  FTC_Manager_RegisterCache( FTC_Manager      manager,
							 FTC_CacheClass   clazz,
							 FTC_Cache       *acache )
  {
	FT_Error   error = FT_ERR( Invalid_Argument );
	FTC_Cache  cache = NULL;

	if ( manager && clazz && acache )
	{
	  FT_Memory  memory = manager->memory;

	  if ( manager->num_caches >= FTC_MAX_CACHES )
	  {
		error = FT_THROW( Too_Many_Caches );
		FT_ERROR(( "FTC_Manager_RegisterCache:"
				   " too many registered caches\n" ));
		goto Exit;
	  }

	  if ( !FT_QALLOC( cache, clazz->cache_size ) )
	  {
		cache->manager   = manager;
		cache->memory    = memory;
		cache->clazz     = clazz[0];
		cache->org_class = clazz;

		/* THIS IS VERY IMPORTANT!  IT WILL WRETCH THE MANAGER */
		/* IF IT IS NOT SET CORRECTLY                          */
		cache->index = manager->num_caches;

		error = clazz->cache_init( cache );
		if ( error )
		{
		  clazz->cache_done( cache );
		  FT_FREE( cache );
		  goto Exit;
		}

		manager->caches[manager->num_caches++] = cache;
	  }
	}

  Exit:
	if ( acache )
	  *acache = cache;
	return error;
  }

  FT_LOCAL_DEF( FT_UInt )
  FTC_Manager_FlushN( FTC_Manager  manager,
					  FT_UInt      count )
  {
	FTC_Node  first = manager->nodes_list;
	FTC_Node  prev, node;
	FT_UInt   result = 0;

	/* try to remove `count' nodes from the list */
	if ( !first || !count )
	  return result;

	/* go to last node -- it's a circular list */
	prev = FTC_NODE_PREV( first );
	do
	{
	  node = prev;
	  prev = FTC_NODE_PREV( node );

	  /* don't touch locked nodes */
	  if ( node->ref_count <= 0 )
	  {
		ftc_node_destroy( node, manager );
		result++;
	  }
	} while ( node != first && result < count );

	return result;
  }

  /* documentation is in ftcache.h */

  FT_EXPORT_DEF( void )
  FTC_Manager_RemoveFaceID( FTC_Manager  manager,
							FTC_FaceID   face_id )
  {
	FT_UInt  nn;

	if ( !manager )
	  return;

	/* this will remove all FTC_SizeNode that correspond to
	 * the face_id as well
	 */
	FTC_MruList_RemoveSelection( &manager->faces,
								 ftc_face_node_compare,
								 face_id );

	for ( nn = 0; nn < manager->num_caches; nn++ )
	  FTC_Cache_RemoveFaceID( manager->caches[nn], face_id );
  }

  /* documentation is in ftcache.h */

  FT_EXPORT_DEF( void )
  FTC_Node_Unref( FTC_Node     node,
				  FTC_Manager  manager )
  {
	if ( node                                    &&
		 manager                                 &&
		 node->cache_index < manager->num_caches )
	  node->ref_count--;
  }

