  /**************************************************************************
   *
   * @Function:
   *   BBox_Conic_Check
   *
   * @Description:
   *   Find the extrema of a 1-dimensional conic Bezier curve and update
   *   a bounding range.  This version uses direct computation, as it
   *   doesn't need square roots.
   *
   * @Input:
   *   y1 ::
   *     The start coordinate.
   *
   *   y2 ::
   *     The coordinate of the control point.
   *
   *   y3 ::
   *     The end coordinate.
   *
   * @InOut:
   *   min ::
   *     The address of the current minimum.
   *
   *   max ::
   *     The address of the current maximum.
   */
  static void
  BBox_Conic_Check( FT_Pos   y1,
					FT_Pos   y2,
					FT_Pos   y3,
					FT_Pos*  min,
					FT_Pos*  max )
  {
	/* This function is only called when a control off-point is outside */
	/* the bbox that contains all on-points.  It finds a local extremum */
	/* within the segment, equal to (y1*y3 - y2*y2)/(y1 - 2*y2 + y3).   */
	/* Or, offsetting from y2, we get                                   */

	y1 -= y2;
	y3 -= y2;
	y2 += FT_MulDiv( y1, y3, y1 + y3 );

	if ( y2 < *min )
	  *min = y2;
	if ( y2 > *max )
	  *max = y2;
  }

  /**************************************************************************
   *
   * @Function:
   *   BBox_Conic_To
   *
   * @Description:
   *   This function is used as a `conic_to' emitter during
   *   FT_Outline_Decompose().  It checks a conic Bezier curve with the
   *   current bounding box, and computes its extrema if necessary to
   *   update it.
   *
   * @Input:
   *   control ::
   *     A pointer to a control point.
   *
   *   to ::
   *     A pointer to the destination vector.
   *
   * @InOut:
   *   user ::
   *     The address of the current walk context.
   *
   * @Return:
   *   Always 0.  Needed for the interface only.
   *
   * @Note:
   *   In the case of a non-monotonous arc, we compute directly the
   *   extremum coordinates, as it is sufficiently fast.
   */
  FT_CALLBACK_DEF( int )
  BBox_Conic_To( const FT_Vector*  control,
				 const FT_Vector*  to,
				 void*             user_ )
  {
	TBBox_Rec*  user = (TBBox_Rec*)user_;

	/* in case `to' is implicit and not included in bbox yet */
	FT_UPDATE_BBOX( to, user->bbox );

	if ( CHECK_X( control, user->bbox ) )
	  BBox_Conic_Check( user->last.x,
						control->x,
						to->x,
						&user->bbox.xMin,
						&user->bbox.xMax );

	if ( CHECK_Y( control, user->bbox ) )
	  BBox_Conic_Check( user->last.y,
						control->y,
						to->y,
						&user->bbox.yMin,
						&user->bbox.yMax );

	user->last = *to;

	return 0;
  }

  /**************************************************************************
   *
   * @Function:
   *   BBox_Cubic_Check
   *
   * @Description:
   *   Find the extrema of a 1-dimensional cubic Bezier curve and
   *   update a bounding range.  This version uses iterative splitting
   *   because it is faster than the exact solution with square roots.
   *
   * @Input:
   *   p1 ::
   *     The start coordinate.
   *
   *   p2 ::
   *     The coordinate of the first control point.
   *
   *   p3 ::
   *     The coordinate of the second control point.
   *
   *   p4 ::
   *     The end coordinate.
   *
   * @InOut:
   *   min ::
   *     The address of the current minimum.
   *
   *   max ::
   *     The address of the current maximum.
   */
  static FT_Pos
  cubic_peak( FT_Pos  q1,
			  FT_Pos  q2,
			  FT_Pos  q3,
			  FT_Pos  q4 )
  {
	FT_Pos  peak = 0;
	FT_Int  shift;

	/* This function finds a peak of a cubic segment if it is above 0    */
	/* using iterative bisection of the segment, or returns 0.           */
	/* The fixed-point arithmetic of bisection is inherently stable      */
	/* but may loose accuracy in the two lowest bits.  To compensate,    */
	/* we upscale the segment if there is room.  Large values may need   */
	/* to be downscaled to avoid overflows during bisection.             */
	/* It is called with either q2 or q3 positive, which is necessary    */
	/* for the peak to exist and avoids undefined FT_MSB.                */

	shift = 27 - FT_MSB( (FT_UInt32)( FT_ABS( q1 ) |
									  FT_ABS( q2 ) |
									  FT_ABS( q3 ) |
									  FT_ABS( q4 ) ) );

	if ( shift > 0 )
	{
	  /* upscaling too much just wastes time */
	  if ( shift > 2 )
		shift = 2;

	  q1 *= 1 << shift;
	  q2 *= 1 << shift;
	  q3 *= 1 << shift;
	  q4 *= 1 << shift;
	}
	else
	{
	  q1 >>= -shift;
	  q2 >>= -shift;
	  q3 >>= -shift;
	  q4 >>= -shift;
	}

	/* for a peak to exist above 0, the cubic segment must have */
	/* at least one of its control off-points above 0.          */
	while ( q2 > 0 || q3 > 0 )
	{
	  /* determine which half contains the maximum and split */
	  if ( q1 + q2 > q3 + q4 ) /* first half */
	  {
		q4 = q4 + q3;
		q3 = q3 + q2;
		q2 = q2 + q1;
		q4 = q4 + q3;
		q3 = q3 + q2;
		q4 = ( q4 + q3 ) >> 3;
		q3 = q3 >> 2;
		q2 = q2 >> 1;
	  }
	  else                     /* second half */
	  {
		q1 = q1 + q2;
		q2 = q2 + q3;
		q3 = q3 + q4;
		q1 = q1 + q2;
		q2 = q2 + q3;
		q1 = ( q1 + q2 ) >> 3;
		q2 = q2 >> 2;
		q3 = q3 >> 1;
	  }

	  /* check whether either end reached the maximum */
	  if ( q1 == q2 && q1 >= q3 )
	  {
		peak = q1;
		break;
	  }
	  if ( q3 == q4 && q2 <= q4 )
	  {
		peak = q4;
		break;
	  }
	}

	if ( shift > 0 )
	  peak >>=  shift;
	else
	  peak <<= -shift;

	return peak;
  }

  static void
  BBox_Cubic_Check( FT_Pos   p1,
					FT_Pos   p2,
					FT_Pos   p3,
					FT_Pos   p4,
					FT_Pos*  min,
					FT_Pos*  max )
  {
	/* This function is only called when a control off-point is outside  */
	/* the bbox that contains all on-points.  So at least one of the     */
	/* conditions below holds and cubic_peak is called with at least one */
	/* non-zero argument.                                                */

	if ( p2 > *max || p3 > *max )
	  *max += cubic_peak( p1 - *max, p2 - *max, p3 - *max, p4 - *max );

	/* now flip the signs to update the minimum */
	if ( p2 < *min || p3 < *min )
	  *min -= cubic_peak( *min - p1, *min - p2, *min - p3, *min - p4 );
  }

  /**************************************************************************
   *
   * @Function:
   *   BBox_Cubic_To
   *
   * @Description:
   *   This function is used as a `cubic_to' emitter during
   *   FT_Outline_Decompose().  It checks a cubic Bezier curve with the
   *   current bounding box, and computes its extrema if necessary to
   *   update it.
   *
   * @Input:
   *   control1 ::
   *     A pointer to the first control point.
   *
   *   control2 ::
   *     A pointer to the second control point.
   *
   *   to ::
   *     A pointer to the destination vector.
   *
   * @InOut:
   *   user ::
   *     The address of the current walk context.
   *
   * @Return:
   *   Always 0.  Needed for the interface only.
   *
   * @Note:
   *   In the case of a non-monotonous arc, we don't compute directly
   *   extremum coordinates, we subdivide instead.
   */
  FT_CALLBACK_DEF( int )
  BBox_Cubic_To( const FT_Vector*  control1,
				 const FT_Vector*  control2,
				 const FT_Vector*  to,
				 void*             user_ )
  {
	TBBox_Rec*  user = (TBBox_Rec*)user_;

	/* We don't need to check `to' since it is always an on-point,    */
	/* thus within the bbox.  Only segments with an off-point outside */
	/* the bbox can possibly reach new extreme values.                */

	if ( CHECK_X( control1, user->bbox ) ||
		 CHECK_X( control2, user->bbox ) )
	  BBox_Cubic_Check( user->last.x,
						control1->x,
						control2->x,
						to->x,
						&user->bbox.xMin,
						&user->bbox.xMax );

	if ( CHECK_Y( control1, user->bbox ) ||
		 CHECK_Y( control2, user->bbox ) )
	  BBox_Cubic_Check( user->last.y,
						control1->y,
						control2->y,
						to->y,
						&user->bbox.yMin,
						&user->bbox.yMax );

	user->last = *to;

	return 0;
  }

