#define VARIANT_BIT         0x80000000UL
#define BASE_GLYPH( code )  ( (FT_UInt32)( (code) & ~VARIANT_BIT ) )

  /* Return the Unicode value corresponding to a given glyph.  Note that */
  /* we do deal with glyph variants by detecting a non-initial dot in    */
  /* the name, as in `A.swash' or `e.final'; in this case, the           */
  /* VARIANT_BIT is set in the return value.                             */
  /*                                                                     */
  FT_CALLBACK_DEF( FT_UInt32 )
  ps_unicode_value( const char*  glyph_name )
  {
	/* If the name begins with `uni', then the glyph name may be a */
	/* hard-coded unicode character code.                          */
	if ( glyph_name[0] == 'u' &&
		 glyph_name[1] == 'n' &&
		 glyph_name[2] == 'i' )
	{
	  /* determine whether the next four characters following are */
	  /* hexadecimal.                                             */

	  /* XXX: Add code to deal with ligatures, i.e. glyph names like */
	  /*      `uniXXXXYYYYZZZZ'...                                   */

	  FT_Int       count;
	  FT_UInt32    value = 0;
	  const char*  p     = glyph_name + 3;

	  for ( count = 4; count > 0; count--, p++ )
	  {
		char          c = *p;
		unsigned int  d;

		d = (unsigned char)c - '0';
		if ( d >= 10 )
		{
		  d = (unsigned char)c - 'A';
		  if ( d >= 6 )
			d = 16;
		  else
			d += 10;
		}

		/* Exit if a non-uppercase hexadecimal character was found   */
		/* -- this also catches character codes below `0' since such */
		/* negative numbers cast to `unsigned int' are far too big.  */
		if ( d >= 16 )
		  break;

		value = ( value << 4 ) + d;
	  }

	  /* there must be exactly four hex digits */
	  if ( count == 0 )
	  {
		if ( *p == '\0' )
		  return value;
		if ( *p == '.' )
		  return (FT_UInt32)( value | VARIANT_BIT );
	  }
	}

	/* If the name begins with `u', followed by four to six uppercase */
	/* hexadecimal digits, it is a hard-coded unicode character code. */
	if ( glyph_name[0] == 'u' )
	{
	  FT_Int       count;
	  FT_UInt32    value = 0;
	  const char*  p     = glyph_name + 1;

	  for ( count = 6; count > 0; count--, p++ )
	  {
		char          c = *p;
		unsigned int  d;

		d = (unsigned char)c - '0';
		if ( d >= 10 )
		{
		  d = (unsigned char)c - 'A';
		  if ( d >= 6 )
			d = 16;
		  else
			d += 10;
		}

		if ( d >= 16 )
		  break;

		value = ( value << 4 ) + d;
	  }

	  if ( count <= 2 )
	  {
		if ( *p == '\0' )
		  return value;
		if ( *p == '.' )
		  return (FT_UInt32)( value | VARIANT_BIT );
	  }
	}

	/* Look for a non-initial dot in the glyph name in order to */
	/* find variants like `A.swash', `e.final', etc.            */
	{
	  FT_UInt32    value = 0;
	  const char*  p     = glyph_name;

	  for ( ; *p && *p != '.'; p++ )
		;

	  /* now look up the glyph in the Adobe Glyph List;      */
	  /* `.notdef', `.null' and the empty name are short cut */
	  if ( p > glyph_name )
	  {
		value = (FT_UInt32)ft_get_adobe_glyph_index( glyph_name, p );

		if ( *p == '.' )
		  value |= (FT_UInt32)VARIANT_BIT;
	  }

	  return value;
	}
  }

  /* ft_qsort callback to sort the unicode map */
  FT_COMPARE_DEF( int )
  compare_uni_maps( const void*  a,
					const void*  b )
  {
	PS_UniMap*  map1 = (PS_UniMap*)a;
	PS_UniMap*  map2 = (PS_UniMap*)b;
	FT_UInt32   unicode1 = BASE_GLYPH( map1->unicode );
	FT_UInt32   unicode2 = BASE_GLYPH( map2->unicode );

	/* sort base glyphs before glyph variants */
	if ( unicode1 == unicode2 )
	{
	  if ( map1->unicode > map2->unicode )
		return 1;
	  else if ( map1->unicode < map2->unicode )
		return -1;
	  else
		return 0;
	}
	else
	{
	  if ( unicode1 > unicode2 )
		return 1;
	  else if ( unicode1 < unicode2 )
		return -1;
	  else
		return 0;
	}
  }

