  static FT_Long
  FT_MulDiv_No_Round( FT_Long  a,
					  FT_Long  b,
					  FT_Long  c )
  {
	FT_Int   s;
	FT_Long  d;

	s = 1;
	if ( a < 0 ) { a = -a; s = -1; }
	if ( b < 0 ) { b = -b; s = -s; }
	if ( c < 0 ) { c = -c; s = -s; }

	d = (FT_Long)( c > 0 ? (FT_Int64)a * b / c
						 : 0x7FFFFFFFL );

	return ( s > 0 ) ? d : -d;
  }

