  /**************************************************************************
   *
   * DEBUG[]:      DEBUG.  Unsupported.
   * Opcode range: 0x4F
   * Stack:        uint32 -->
   *
   * Note: The original instruction pops a value from the stack.
   */
  static void
  Ins_DEBUG( TT_ExecContext  exc )
  {
	exc->error = FT_THROW( Debug_OpCode );
  }

  /**************************************************************************
   *
   * ROUND[ab]:    ROUND value
   * Opcode range: 0x68-0x6B
   * Stack:        f26.6 --> f26.6
   */
  static void
  Ins_ROUND( TT_ExecContext  exc,
			 FT_Long*        args )
  {
	args[0] = exc->func_round( exc, args[0], exc->opcode & 3 );
  }

  /**************************************************************************
   *
   * NROUND[ab]:   No ROUNDing of value
   * Opcode range: 0x6C-0x6F
   * Stack:        f26.6 --> f26.6
   */
  static void
  Ins_NROUND( TT_ExecContext  exc,
			  FT_Long*        args )
  {
	args[0] = Round_None( exc, args[0], exc->opcode & 3 );
  }

  /**************************************************************************
   *
   * MAX[]:        MAXimum
   * Opcode range: 0x8B
   * Stack:        int32? int32? --> int32
   */
  static void
  Ins_MAX( FT_Long*  args )
  {
	if ( args[1] > args[0] )
	  args[0] = args[1];
  }

  /**************************************************************************
   *
   * MIN[]:        MINimum
   * Opcode range: 0x8C
   * Stack:        int32? int32? --> int32
   */
  static void
  Ins_MIN( FT_Long*  args )
  {
	if ( args[1] < args[0] )
	  args[0] = args[1];
  }

  /**************************************************************************
   *
   * MINDEX[]:     Move INDEXed element
   * Opcode range: 0x26
   * Stack:        int32? --> StkElt
   */
  static void
  Ins_MINDEX( TT_ExecContext  exc,
			  FT_Long*        args )
  {
	FT_Long  L, K;

	L = args[0];

	if ( L <= 0 || L > exc->args )
	{
	  if ( exc->pedantic_hinting )
		exc->error = FT_THROW( Invalid_Reference );
	}
	else
	{
	  K = exc->stack[exc->args - L];

	  FT_ARRAY_MOVE( &exc->stack[exc->args - L    ],
					 &exc->stack[exc->args - L + 1],
					 ( L - 1 ) );

	  exc->stack[exc->args - 1] = K;
	}
  }

  /**************************************************************************
   *
   * CINDEX[]:     Copy INDEXed element
   * Opcode range: 0x25
   * Stack:        int32 --> StkElt
   */
  static void
  Ins_CINDEX( TT_ExecContext  exc,
			  FT_Long*        args )
  {
	FT_Long  L;

	L = args[0];

	if ( L <= 0 || L > exc->args )
	{
	  if ( exc->pedantic_hinting )
		exc->error = FT_THROW( Invalid_Reference );
	  args[0] = 0;
	}
	else
	  args[0] = exc->stack[exc->args - L];
  }

  /**************************************************************************
   *
   * ROLL[]:       ROLL top three elements
   * Opcode range: 0x8A
   * Stack:        3 * StkElt --> 3 * StkElt
   */
  static void
  Ins_ROLL( FT_Long*  args )
  {
	FT_Long  A, B, C;

	A = args[2];
	B = args[1];
	C = args[0];

	args[2] = C;
	args[1] = A;
	args[0] = B;
  }

  /**************************************************************************
   *
   * MANAGING THE FLOW OF CONTROL
   *
   */

  /**************************************************************************
   *
   * SLOOP[]:      Set LOOP variable
   * Opcode range: 0x17
   * Stack:        int32? -->
   */
  static void
  Ins_SLOOP( TT_ExecContext  exc,
			 FT_Long*        args )
  {
	if ( args[0] < 0 )
	  exc->error = FT_THROW( Bad_Argument );
	else
	{
	  /* we heuristically limit the number of loops to 16 bits */
	  exc->GS.loop = args[0] > 0xFFFFL ? 0xFFFFL : args[0];
	}
  }

  static FT_Bool
  SkipCode( TT_ExecContext  exc )
  {
	exc->IP += exc->length;

	if ( exc->IP < exc->codeSize )
	{
	  exc->opcode = exc->code[exc->IP];

	  exc->length = opcode_length[exc->opcode];
	  if ( exc->length < 0 )
	  {
		if ( exc->IP + 1 >= exc->codeSize )
		  goto Fail_Overflow;
		exc->length = 2 - exc->length * exc->code[exc->IP + 1];
	  }

	  if ( exc->IP + exc->length <= exc->codeSize )
		return SUCCESS;
	}

  Fail_Overflow:
	exc->error = FT_THROW( Code_Overflow );
	return FAILURE;
  }

  /**************************************************************************
   *
   * IF[]:         IF test
   * Opcode range: 0x58
   * Stack:        StkElt -->
   */
  static void
  Ins_IF( TT_ExecContext  exc,
		  FT_Long*        args )
  {
	FT_Int   nIfs;
	FT_Bool  Out;

	if ( args[0] != 0 )
	  return;

	nIfs = 1;
	Out = 0;

	do
	{
	  if ( SkipCode( exc ) == FAILURE )
		return;

	  switch ( exc->opcode )
	  {
	  case 0x58:      /* IF */
		nIfs++;
		break;

	  case 0x1B:      /* ELSE */
		Out = FT_BOOL( nIfs == 1 );
		break;

	  case 0x59:      /* EIF */
		nIfs--;
		Out = FT_BOOL( nIfs == 0 );
		break;
	  }
	} while ( Out == 0 );
  }

  /**************************************************************************
   *
   * ELSE[]:       ELSE
   * Opcode range: 0x1B
   * Stack:        -->
   */
  static void
  Ins_ELSE( TT_ExecContext  exc )
  {
	FT_Int  nIfs;

	nIfs = 1;

	do
	{
	  if ( SkipCode( exc ) == FAILURE )
		return;

	  switch ( exc->opcode )
	  {
	  case 0x58:    /* IF */
		nIfs++;
		break;

	  case 0x59:    /* EIF */
		nIfs--;
		break;
	  }
	} while ( nIfs != 0 );
  }

  /**************************************************************************
   *
   * EIF[]:        End IF
   * Opcode range: 0x59
   * Stack:        -->
   */
  static void
  Ins_EIF( void )
  {
	/* nothing to do */
  }

  /**************************************************************************
   *
   * JMPR[]:       JuMP Relative
   * Opcode range: 0x1C
   * Stack:        int32 -->
   */
  static void
  Ins_JMPR( TT_ExecContext  exc,
			FT_Long*        args )
  {
	if ( args[0] == 0 && exc->args == 0 )
	{
	  exc->error = FT_THROW( Bad_Argument );
	  return;
	}

	exc->IP = ADD_LONG( exc->IP, args[0] );
	if ( exc->IP < 0                                             ||
		 ( exc->callTop > 0                                    &&
		   exc->IP > exc->callStack[exc->callTop - 1].Def->end ) )
	{
	  exc->error = FT_THROW( Bad_Argument );
	  return;
	}

	exc->step_ins = FALSE;

	if ( args[0] < 0 )
	{
	  if ( ++exc->neg_jump_counter > exc->neg_jump_counter_max )
		exc->error = FT_THROW( Execution_Too_Long );
	}
  }

  /**************************************************************************
   *
   * JROT[]:       Jump Relative On True
   * Opcode range: 0x78
   * Stack:        StkElt int32 -->
   */
  static void
  Ins_JROT( TT_ExecContext  exc,
			FT_Long*        args )
  {
	if ( args[1] != 0 )
	  Ins_JMPR( exc, args );
  }

  /**************************************************************************
   *
   * JROF[]:       Jump Relative On False
   * Opcode range: 0x79
   * Stack:        StkElt int32 -->
   */
  static void
  Ins_JROF( TT_ExecContext  exc,
			FT_Long*        args )
  {
	if ( args[1] == 0 )
	  Ins_JMPR( exc, args );
  }

  /**************************************************************************
   *
   * DEFINING AND USING FUNCTIONS AND INSTRUCTIONS
   *
   */

  /**************************************************************************
   *
   * FDEF[]:       Function DEFinition
   * Opcode range: 0x2C
   * Stack:        uint32 -->
   */
  static void
  Ins_FDEF( TT_ExecContext  exc,
			FT_Long*        args )
  {
	FT_ULong       n;
	TT_DefRecord*  rec;
	TT_DefRecord*  limit;

	/* FDEF is only allowed in `prep' or `fpgm' */
	if ( exc->iniRange == tt_coderange_glyph )
	{
	  exc->error = FT_THROW( DEF_In_Glyf_Bytecode );
	  return;
	}

	/* some font programs are broken enough to redefine functions! */
	/* We will then parse the current table.                       */

	rec   = exc->FDefs;
	limit = FT_OFFSET( rec, exc->numFDefs );
	n     = (FT_ULong)args[0];

	for ( ; rec < limit; rec++ )
	{
	  if ( rec->opc == n )
		break;
	}

	if ( rec == limit )
	{
	  /* check that there is enough room for new functions */
	  if ( exc->numFDefs >= exc->maxFDefs )
	  {
		exc->error = FT_THROW( Too_Many_Function_Defs );
		return;
	  }
	  exc->numFDefs++;
	}

	/* Although FDEF takes unsigned 32-bit integer,  */
	/* func # must be within unsigned 16-bit integer */
	if ( n > 0xFFFFU )
	{
	  exc->error = FT_THROW( Too_Many_Function_Defs );
	  return;
	}

	rec->range          = exc->curRange;
	rec->opc            = (FT_UInt16)n;
	rec->start          = exc->IP + 1;
	rec->active         = TRUE;

	if ( n > exc->maxFunc )
	  exc->maxFunc = (FT_UInt16)n;

	/* Now skip the whole function definition. */
	/* We don't allow nested IDEFS & FDEFs.    */

	while ( SkipCode( exc ) == SUCCESS )
	{
	  switch ( exc->opcode )
	  {
	  case 0x89:    /* IDEF */
	  case 0x2C:    /* FDEF */
		exc->error = FT_THROW( Nested_DEFS );
		return;

	  case 0x2D:   /* ENDF */
		rec->end = exc->IP;
		return;
	  }
	}
  }

  /**************************************************************************
   *
   * ENDF[]:       END Function definition
   * Opcode range: 0x2D
   * Stack:        -->
   */
  static void
  Ins_ENDF( TT_ExecContext  exc )
  {
	TT_CallRec*  pRec;

	if ( exc->callTop <= 0 )     /* We encountered an ENDF without a call */
	{
	  exc->error = FT_THROW( ENDF_In_Exec_Stream );
	  return;
	}

	exc->callTop--;

	pRec = &exc->callStack[exc->callTop];

	pRec->Cur_Count--;

	exc->step_ins = FALSE;

	if ( pRec->Cur_Count > 0 )
	{
	  exc->callTop++;
	  exc->IP = pRec->Def->start;
	}
	else
	  /* Loop through the current function */
	  Ins_Goto_CodeRange( exc, pRec->Caller_Range, pRec->Caller_IP );

	/* Exit the current call frame.                      */

	/* NOTE: If the last instruction of a program is a   */
	/*       CALL or LOOPCALL, the return address is     */
	/*       always out of the code range.  This is a    */
	/*       valid address, and it is why we do not test */
	/*       the result of Ins_Goto_CodeRange() here!    */
  }

  /**************************************************************************
   *
   * CALL[]:       CALL function
   * Opcode range: 0x2B
   * Stack:        uint32? -->
   */
  static void
  Ins_CALL( TT_ExecContext  exc,
			FT_Long*        args )
  {
	FT_ULong       F;
	TT_CallRec*    pCrec;
	TT_DefRecord*  def;

	/* first of all, check the index */

	F = (FT_ULong)args[0];
	if ( BOUNDSL( F, exc->maxFunc + 1 ) )
	  goto Fail;

	if ( !exc->FDefs )
	  goto Fail;

	/* Except for some old Apple fonts, all functions in a TrueType */
	/* font are defined in increasing order, starting from 0.  This */
	/* means that we normally have                                  */
	/*                                                              */
	/*    exc->maxFunc+1 == exc->numFDefs                           */
	/*    exc->FDefs[n].opc == n for n in 0..exc->maxFunc           */
	/*                                                              */
	/* If this isn't true, we need to look up the function table.   */

	def = exc->FDefs + F;
	if ( exc->maxFunc + 1 != exc->numFDefs || def->opc != F )
	{
	  /* look up the FDefs table */
	  TT_DefRecord*  limit;

	  def   = exc->FDefs;
	  limit = def + exc->numFDefs;

	  while ( def < limit && def->opc != F )
		def++;

	  if ( def == limit )
		goto Fail;
	}

	/* check that the function is active */
	if ( !def->active )
	  goto Fail;

	/* check the call stack */
	if ( exc->callTop >= exc->callSize )
	{
	  exc->error = FT_THROW( Stack_Overflow );
	  return;
	}

	pCrec = exc->callStack + exc->callTop;

	pCrec->Caller_Range = exc->curRange;
	pCrec->Caller_IP    = exc->IP + 1;
	pCrec->Cur_Count    = 1;
	pCrec->Def          = def;

	exc->callTop++;

	Ins_Goto_CodeRange( exc, def->range, def->start );

	exc->step_ins = FALSE;

	return;

  Fail:
	exc->error = FT_THROW( Invalid_Reference );
  }

  /**************************************************************************
   *
   * LOOPCALL[]:   LOOP and CALL function
   * Opcode range: 0x2A
   * Stack:        uint32? Eint16? -->
   */
  static void
  Ins_LOOPCALL( TT_ExecContext  exc,
				FT_Long*        args )
  {
	FT_ULong       F;
	TT_CallRec*    pCrec;
	TT_DefRecord*  def;

	/* first of all, check the index */
	F = (FT_ULong)args[1];
	if ( BOUNDSL( F, exc->maxFunc + 1 ) )
	  goto Fail;

	/* Except for some old Apple fonts, all functions in a TrueType */
	/* font are defined in increasing order, starting from 0.  This */
	/* means that we normally have                                  */
	/*                                                              */
	/*    exc->maxFunc+1 == exc->numFDefs                           */
	/*    exc->FDefs[n].opc == n for n in 0..exc->maxFunc           */
	/*                                                              */
	/* If this isn't true, we need to look up the function table.   */

	def = FT_OFFSET( exc->FDefs, F );
	if ( exc->maxFunc + 1 != exc->numFDefs || def->opc != F )
	{
	  /* look up the FDefs table */
	  TT_DefRecord*  limit;

	  def   = exc->FDefs;
	  limit = FT_OFFSET( def, exc->numFDefs );

	  while ( def < limit && def->opc != F )
		def++;

	  if ( def == limit )
		goto Fail;
	}

	/* check that the function is active */
	if ( !def->active )
	  goto Fail;

	/* check stack */
	if ( exc->callTop >= exc->callSize )
	{
	  exc->error = FT_THROW( Stack_Overflow );
	  return;
	}

	if ( args[0] > 0 )
	{
	  pCrec = exc->callStack + exc->callTop;

	  pCrec->Caller_Range = exc->curRange;
	  pCrec->Caller_IP    = exc->IP + 1;
	  pCrec->Cur_Count    = (FT_Int)args[0];
	  pCrec->Def          = def;

	  exc->callTop++;

	  Ins_Goto_CodeRange( exc, def->range, def->start );

	  exc->step_ins = FALSE;

	  exc->loopcall_counter += (FT_ULong)args[0];
	  if ( exc->loopcall_counter > exc->loopcall_counter_max )
		exc->error = FT_THROW( Execution_Too_Long );
	}

	return;

  Fail:
	exc->error = FT_THROW( Invalid_Reference );
  }

  /**************************************************************************
   *
   * IDEF[]:       Instruction DEFinition
   * Opcode range: 0x89
   * Stack:        Eint8 -->
   */
  static void
  Ins_IDEF( TT_ExecContext  exc,
			FT_Long*        args )
  {
	TT_DefRecord*  def;
	TT_DefRecord*  limit;

	/* we enable IDEF only in `prep' or `fpgm' */
	if ( exc->iniRange == tt_coderange_glyph )
	{
	  exc->error = FT_THROW( DEF_In_Glyf_Bytecode );
	  return;
	}

	/*  First of all, look for the same function in our table */

	def   = exc->IDefs;
	limit = FT_OFFSET( def, exc->numIDefs );

	for ( ; def < limit; def++ )
	  if ( def->opc == (FT_ULong)args[0] )
		break;

	if ( def == limit )
	{
	  /* check that there is enough room for a new instruction */
	  if ( exc->numIDefs >= exc->maxIDefs )
	  {
		exc->error = FT_THROW( Too_Many_Instruction_Defs );
		return;
	  }
	  exc->numIDefs++;
	}

	/* opcode must be unsigned 8-bit integer */
	if ( 0 > args[0] || args[0] > 0x00FF )
	{
	  exc->error = FT_THROW( Too_Many_Instruction_Defs );
	  return;
	}

	def->opc    = (FT_Byte)args[0];
	def->start  = exc->IP + 1;
	def->range  = exc->curRange;
	def->active = TRUE;

	if ( (FT_ULong)args[0] > exc->maxIns )
	  exc->maxIns = (FT_Byte)args[0];

	/* Now skip the whole function definition. */
	/* We don't allow nested IDEFs & FDEFs.    */

	while ( SkipCode( exc ) == SUCCESS )
	{
	  switch ( exc->opcode )
	  {
	  case 0x89:   /* IDEF */
	  case 0x2C:   /* FDEF */
		exc->error = FT_THROW( Nested_DEFS );
		return;
	  case 0x2D:   /* ENDF */
		def->end = exc->IP;
		return;
	  }
	}
  }

  /**************************************************************************
   *
   * PUSHING DATA ONTO THE INTERPRETER STACK
   *
   */

  /**************************************************************************
   *
   * NPUSHB[]:     PUSH N Bytes
   * Opcode range: 0x40
   * Stack:        --> uint32...
   */
  static void
  Ins_NPUSHB( TT_ExecContext  exc,
			  FT_Long*        args )
  {
	FT_UShort  L, K;

	L = (FT_UShort)exc->code[exc->IP + 1];

	if ( BOUNDS( L, exc->stackSize + 1 - exc->top ) )
	{
	  exc->error = FT_THROW( Stack_Overflow );
	  return;
	}

	for ( K = 1; K <= L; K++ )
	  args[K - 1] = exc->code[exc->IP + K + 1];

	exc->new_top += L;
  }

  /**************************************************************************
   *
   * NPUSHW[]:     PUSH N Words
   * Opcode range: 0x41
   * Stack:        --> int32...
   */
  static void
  Ins_NPUSHW( TT_ExecContext  exc,
			  FT_Long*        args )
  {
	FT_UShort  L, K;

	L = (FT_UShort)exc->code[exc->IP + 1];

	if ( BOUNDS( L, exc->stackSize + 1 - exc->top ) )
	{
	  exc->error = FT_THROW( Stack_Overflow );
	  return;
	}

	exc->IP += 2;

	for ( K = 0; K < L; K++ )
	  args[K] = GetShortIns( exc );

	exc->step_ins = FALSE;
	exc->new_top += L;
  }

  /**************************************************************************
   *
   * PUSHB[abc]:   PUSH Bytes
   * Opcode range: 0xB0-0xB7
   * Stack:        --> uint32...
   */
  static void
  Ins_PUSHB( TT_ExecContext  exc,
			 FT_Long*        args )
  {
	FT_UShort  L, K;

	L = (FT_UShort)( exc->opcode - 0xB0 + 1 );

	if ( BOUNDS( L, exc->stackSize + 1 - exc->top ) )
	{
	  exc->error = FT_THROW( Stack_Overflow );
	  return;
	}

	for ( K = 1; K <= L; K++ )
	  args[K - 1] = exc->code[exc->IP + K];
  }

  /**************************************************************************
   *
   * PUSHW[abc]:   PUSH Words
   * Opcode range: 0xB8-0xBF
   * Stack:        --> int32...
   */
  static void
  Ins_PUSHW( TT_ExecContext  exc,
			 FT_Long*        args )
  {
	FT_UShort  L, K;

	L = (FT_UShort)( exc->opcode - 0xB8 + 1 );

	if ( BOUNDS( L, exc->stackSize + 1 - exc->top ) )
	{
	  exc->error = FT_THROW( Stack_Overflow );
	  return;
	}

	exc->IP++;

	for ( K = 0; K < L; K++ )
	  args[K] = GetShortIns( exc );

	exc->step_ins = FALSE;
  }

  /**************************************************************************
   *
   * MANAGING THE GRAPHICS STATE
   *
   */

  static FT_Bool
  Ins_SxVTL( TT_ExecContext  exc,
			 FT_UShort       aIdx1,
			 FT_UShort       aIdx2,
			 FT_UnitVector*  Vec )
  {
	FT_Long     A, B, C;
	FT_Vector*  p1;
	FT_Vector*  p2;

	FT_Byte  opcode = exc->opcode;

	if ( BOUNDS( aIdx1, exc->zp2.n_points ) ||
		 BOUNDS( aIdx2, exc->zp1.n_points ) )
	{
	  if ( exc->pedantic_hinting )
		exc->error = FT_THROW( Invalid_Reference );
	  return FAILURE;
	}

	p1 = exc->zp1.cur + aIdx2;
	p2 = exc->zp2.cur + aIdx1;

	A = SUB_LONG( p1->x, p2->x );
	B = SUB_LONG( p1->y, p2->y );

	/* If p1 == p2, SPvTL and SFvTL behave the same as */
	/* SPvTCA[X] and SFvTCA[X], respectively.          */
	/*                                                 */
	/* Confirmed by Greg Hitchcock.                    */

	if ( A == 0 && B == 0 )
	{
	  A      = 0x4000;
	  opcode = 0;
	}

	if ( ( opcode & 1 ) != 0 )
	{
	  C = B;   /* counter-clockwise rotation */
	  B = A;
	  A = NEG_LONG( C );
	}

	Normalize( A, B, Vec );

	return SUCCESS;
  }

  /**************************************************************************
   *
   * SVTCA[a]:     Set (F and P) Vectors to Coordinate Axis
   * Opcode range: 0x00-0x01
   * Stack:        -->
   *
   * SPvTCA[a]:    Set PVector to Coordinate Axis
   * Opcode range: 0x02-0x03
   * Stack:        -->
   *
   * SFvTCA[a]:    Set FVector to Coordinate Axis
   * Opcode range: 0x04-0x05
   * Stack:        -->
   */
  static void
  Ins_SxyTCA( TT_ExecContext  exc )
  {
	FT_Short  AA, BB;

	FT_Byte  opcode = exc->opcode;

	AA = (FT_Short)( ( opcode & 1 ) << 14 );
	BB = (FT_Short)( AA ^ 0x4000 );

	if ( opcode < 4 )
	{
	  exc->GS.projVector.x = AA;
	  exc->GS.projVector.y = BB;

	  exc->GS.dualVector.x = AA;
	  exc->GS.dualVector.y = BB;
	}

	if ( ( opcode & 2 ) == 0 )
	{
	  exc->GS.freeVector.x = AA;
	  exc->GS.freeVector.y = BB;
	}

	Compute_Funcs( exc );
  }

  /**************************************************************************
   *
   * SPvTL[a]:     Set PVector To Line
   * Opcode range: 0x06-0x07
   * Stack:        uint32 uint32 -->
   */
  static void
  Ins_SPVTL( TT_ExecContext  exc,
			 FT_Long*        args )
  {
	if ( Ins_SxVTL( exc,
					(FT_UShort)args[1],
					(FT_UShort)args[0],
					&exc->GS.projVector ) == SUCCESS )
	{
	  exc->GS.dualVector = exc->GS.projVector;
	  Compute_Funcs( exc );
	}
  }

  /**************************************************************************
   *
   * SFvTL[a]:     Set FVector To Line
   * Opcode range: 0x08-0x09
   * Stack:        uint32 uint32 -->
   */
  static void
  Ins_SFVTL( TT_ExecContext  exc,
			 FT_Long*        args )
  {
	if ( Ins_SxVTL( exc,
					(FT_UShort)args[1],
					(FT_UShort)args[0],
					&exc->GS.freeVector ) == SUCCESS )
	{
	  Compute_Funcs( exc );
	}
  }

  /**************************************************************************
   *
   * SFvTPv[]:     Set FVector To PVector
   * Opcode range: 0x0E
   * Stack:        -->
   */
  static void
  Ins_SFVTPV( TT_ExecContext  exc )
  {
	exc->GS.freeVector = exc->GS.projVector;
	Compute_Funcs( exc );
  }

  /**************************************************************************
   *
   * SPvFS[]:      Set PVector From Stack
   * Opcode range: 0x0A
   * Stack:        f2.14 f2.14 -->
   */
  static void
  Ins_SPVFS( TT_ExecContext  exc,
			 FT_Long*        args )
  {
	FT_Short  S;
	FT_Long   X, Y;

	/* Only use low 16bits, then sign extend */
	S = (FT_Short)args[1];
	Y = (FT_Long)S;
	S = (FT_Short)args[0];
	X = (FT_Long)S;

	Normalize( X, Y, &exc->GS.projVector );

	exc->GS.dualVector = exc->GS.projVector;
	Compute_Funcs( exc );
  }

  /**************************************************************************
   *
   * SFvFS[]:      Set FVector From Stack
   * Opcode range: 0x0B
   * Stack:        f2.14 f2.14 -->
   */
  static void
  Ins_SFVFS( TT_ExecContext  exc,
			 FT_Long*        args )
  {
	FT_Short  S;
	FT_Long   X, Y;

	/* Only use low 16bits, then sign extend */
	S = (FT_Short)args[1];
	Y = (FT_Long)S;
	S = (FT_Short)args[0];
	X = S;

	Normalize( X, Y, &exc->GS.freeVector );
	Compute_Funcs( exc );
  }

