  /**************************************************************************
   *
   * GC[a]:        Get Coordinate projected onto
   * Opcode range: 0x46-0x47
   * Stack:        uint32 --> f26.6
   *
   * XXX: UNDOCUMENTED: Measures from the original glyph must be taken
   *      along the dual projection vector!
   */
  static void
  Ins_GC( TT_ExecContext  exc,
		  FT_Long*        args )
  {
	FT_ULong    L;
	FT_F26Dot6  R;

	L = (FT_ULong)args[0];

	if ( BOUNDSL( L, exc->zp2.n_points ) )
	{
	  if ( exc->pedantic_hinting )
		exc->error = FT_THROW( Invalid_Reference );
	  R = 0;
	}
	else
	{
	  if ( exc->opcode & 1 )
		R = FAST_DUALPROJ( &exc->zp2.org[L] );
	  else
		R = FAST_PROJECT( &exc->zp2.cur[L] );
	}

	args[0] = R;
  }

  /**************************************************************************
   *
   * SCFS[]:       Set Coordinate From Stack
   * Opcode range: 0x48
   * Stack:        f26.6 uint32 -->
   *
   * Formula:
   *
   *   OA := OA + ( value - OA.p )/( f.p ) * f
   */
  static void
  Ins_SCFS( TT_ExecContext  exc,
			FT_Long*        args )
  {
	FT_Long    K;
	FT_UShort  L;

	L = (FT_UShort)args[0];

	if ( BOUNDS( L, exc->zp2.n_points ) )
	{
	  if ( exc->pedantic_hinting )
		exc->error = FT_THROW( Invalid_Reference );
	  return;
	}

	K = FAST_PROJECT( &exc->zp2.cur[L] );

	exc->func_move( exc, &exc->zp2, L, SUB_LONG( args[1], K ) );

	/* UNDOCUMENTED!  The MS rasterizer does that with */
	/* twilight points (confirmed by Greg Hitchcock)   */
	if ( exc->GS.gep2 == 0 )
	  exc->zp2.org[L] = exc->zp2.cur[L];
  }

  /**************************************************************************
   *
   * MD[a]:        Measure Distance
   * Opcode range: 0x49-0x4A
   * Stack:        uint32 uint32 --> f26.6
   *
   * XXX: UNDOCUMENTED: Measure taken in the original glyph must be along
   *                    the dual projection vector.
   *
   * XXX: UNDOCUMENTED: Flag attributes are inverted!
   *                      0 => measure distance in original outline
   *                      1 => measure distance in grid-fitted outline
   *
   * XXX: UNDOCUMENTED: `zp0 - zp1', and not `zp2 - zp1!
   */
  static void
  Ins_MD( TT_ExecContext  exc,
		  FT_Long*        args )
  {
	FT_UShort   K, L;
	FT_F26Dot6  D;

	K = (FT_UShort)args[1];
	L = (FT_UShort)args[0];

	if ( BOUNDS( L, exc->zp0.n_points ) ||
		 BOUNDS( K, exc->zp1.n_points ) )
	{
	  if ( exc->pedantic_hinting )
		exc->error = FT_THROW( Invalid_Reference );
	  D = 0;
	}
	else
	{
	  if ( exc->opcode & 1 )
		D = PROJECT( exc->zp0.cur + L, exc->zp1.cur + K );
	  else
	  {
		/* XXX: UNDOCUMENTED: twilight zone special case */

		if ( exc->GS.gep0 == 0 || exc->GS.gep1 == 0 )
		{
		  FT_Vector*  vec1 = exc->zp0.org + L;
		  FT_Vector*  vec2 = exc->zp1.org + K;

		  D = DUALPROJ( vec1, vec2 );
		}
		else
		{
		  FT_Vector*  vec1 = exc->zp0.orus + L;
		  FT_Vector*  vec2 = exc->zp1.orus + K;

		  if ( exc->metrics.x_scale == exc->metrics.y_scale )
		  {
			/* this should be faster */
			D = DUALPROJ( vec1, vec2 );
			D = FT_MulFix( D, exc->metrics.x_scale );
		  }
		  else
		  {
			FT_Vector  vec;

			vec.x = FT_MulFix( vec1->x - vec2->x, exc->metrics.x_scale );
			vec.y = FT_MulFix( vec1->y - vec2->y, exc->metrics.y_scale );

			D = FAST_DUALPROJ( &vec );
		  }
		}
	  }
	}

	args[0] = D;
  }

  /**************************************************************************
   *
   * SDPvTL[a]:    Set Dual PVector to Line
   * Opcode range: 0x86-0x87
   * Stack:        uint32 uint32 -->
   */
  static void
  Ins_SDPVTL( TT_ExecContext  exc,
			  FT_Long*        args )
  {
	FT_Long    A, B, C;
	FT_UShort  p1, p2;            /* was FT_Int in pas type ERROR */

	FT_Byte  opcode = exc->opcode;

	p1 = (FT_UShort)args[1];
	p2 = (FT_UShort)args[0];

	if ( BOUNDS( p2, exc->zp1.n_points ) ||
		 BOUNDS( p1, exc->zp2.n_points ) )
	{
	  if ( exc->pedantic_hinting )
		exc->error = FT_THROW( Invalid_Reference );
	  return;
	}

	{
	  FT_Vector*  v1 = exc->zp1.org + p2;
	  FT_Vector*  v2 = exc->zp2.org + p1;

	  A = SUB_LONG( v1->x, v2->x );
	  B = SUB_LONG( v1->y, v2->y );

	  /* If v1 == v2, SDPvTL behaves the same as */
	  /* SVTCA[X], respectively.                 */
	  /*                                         */
	  /* Confirmed by Greg Hitchcock.            */

	  if ( A == 0 && B == 0 )
	  {
		A      = 0x4000;
		opcode = 0;
	  }
	}

	if ( ( opcode & 1 ) != 0 )
	{
	  C = B;   /* counter-clockwise rotation */
	  B = A;
	  A = NEG_LONG( C );
	}

	Normalize( A, B, &exc->GS.dualVector );

	{
	  FT_Vector*  v1 = exc->zp1.cur + p2;
	  FT_Vector*  v2 = exc->zp2.cur + p1;

	  A = SUB_LONG( v1->x, v2->x );
	  B = SUB_LONG( v1->y, v2->y );

	  if ( A == 0 && B == 0 )
	  {
		A      = 0x4000;
		opcode = 0;
	  }
	}

	if ( ( opcode & 1 ) != 0 )
	{
	  C = B;   /* counter-clockwise rotation */
	  B = A;
	  A = NEG_LONG( C );
	}

	Normalize( A, B, &exc->GS.projVector );
	Compute_Funcs( exc );
  }

  /**************************************************************************
   *
   * SZP0[]:       Set Zone Pointer 0
   * Opcode range: 0x13
   * Stack:        uint32 -->
   */
  static void
  Ins_SZP0( TT_ExecContext  exc,
			FT_Long*        args )
  {
	switch ( (FT_Int)args[0] )
	{
	case 0:
	  exc->zp0 = exc->twilight;
	  break;

	case 1:
	  exc->zp0 = exc->pts;
	  break;

	default:
	  if ( exc->pedantic_hinting )
		exc->error = FT_THROW( Invalid_Reference );
	  return;
	}

	exc->GS.gep0 = (FT_UShort)args[0];
  }

