  static FT_Error
  ft_svg_transform( FT_Renderer       renderer,
					FT_GlyphSlot      slot,
					const FT_Matrix*  _matrix,
					const FT_Vector*  _delta )
  {
	FT_SVG_Document  doc    = (FT_SVG_Document)slot->other;
	FT_Matrix*       matrix = (FT_Matrix*)_matrix;
	FT_Vector*       delta  = (FT_Vector*)_delta;

	FT_Matrix  tmp_matrix;
	FT_Vector  tmp_delta;

	FT_Matrix  a, b;
	FT_Pos     x, y;

	FT_UNUSED( renderer );

	if ( !matrix )
	{
	  tmp_matrix.xx = 0x10000;
	  tmp_matrix.xy = 0;
	  tmp_matrix.yx = 0;
	  tmp_matrix.yy = 0x10000;

	  matrix = &tmp_matrix;
	}

	if ( !delta )
	{
	  tmp_delta.x = 0;
	  tmp_delta.y = 0;

	  delta = &tmp_delta;
	}

	a = doc->transform;
	b = *matrix;
	FT_Matrix_Multiply( &b, &a );

	x = ADD_LONG( ADD_LONG( FT_MulFix( matrix->xx, doc->delta.x ),
							FT_MulFix( matrix->xy, doc->delta.y ) ),
				  delta->x );
	y = ADD_LONG( ADD_LONG( FT_MulFix( matrix->yx, doc->delta.x ),
							FT_MulFix( matrix->yy, doc->delta.y ) ),
				  delta->y );

	doc->delta.x   = x;
	doc->delta.y   = y;
	doc->transform = a;

	return FT_Err_Ok;
  }

