  /* it is better to use FreeType memory routines instead of raw
	 'malloc/free' */

  static voidpf
  ft_gzip_alloc( voidpf  opaque,
				 uInt    items,
				 uInt    size )
  {
	FT_Memory   memory = (FT_Memory)opaque;
	FT_ULong    sz     = (FT_ULong)size * items;
	FT_Error    error;
	FT_Pointer  p      = NULL;

	/* allocate and zero out */
	FT_MEM_ALLOC( p, sz );
	return p;
  }

  static void
  ft_gzip_free( voidpf  opaque,
				voidpf  address )
  {
	FT_Memory  memory = (FT_Memory)opaque;

	FT_MEM_FREE( address );
  }

/***************************************************************************/
/***************************************************************************/
